const SLOTS = [
  { group:'Home slider (full width)', size:'1920 × 1080, landscape', items:[
    ['hero-1','Slide 1: Wooden Furniture','A finished teak mandir, sofa or dining set in a customer’s home'],
    ['hero-2','Slide 2: Modular Kitchen & Home Interior','A completed kitchen or wardrobe wall, shot straight on'],
    ['hero-3','Slide 3: Lathe Works','Turned pillars or a baluster railing on site, or the lathe in action'] ]},
  { group:'Explore tiles (home)', size:'1000 × 1250, portrait', items:[
    ['cat-sofa','Wooden Sofas',''],['cat-dining','Dining Sets',''],['cat-mandir','Home Mandirs',''],['cat-zula','Zulas',''],
    ['cat-kitchen','Modular Kitchens',''],['cat-wardrobe','Wardrobes',''],['cat-pillar','Wooden Pillars',''],['cat-baluster','Balusters & Railings',''] ]},
  { group:'Department cards (home)', size:'1500 × 1000, landscape', items:[
    ['dept-wooden','Wooden Furniture card',''],['dept-modular','Modular Kitchen & Home Interior card',''],['dept-lathe','Lathe Works card',''] ]},
  { group:'Department page main photo', size:'1200 × 1500, portrait (Lathe: 1500 × 1200 landscape)', items:[
    ['seg-wooden','Wooden Furniture page',''],['seg-modular','Modular Kitchen & Home Interior page',''],['seg-lathe','Lathe Works page','Replaces the lathe animation'] ]},
  { group:'Inside our workshop (home)', size:'1000 × 1250, portrait', items:[
    ['work-1','Turning on the lathe',''],['work-2','Joinery by hand',''],['work-3','Polishing & finishing',''],['work-4','Installation on site',''] ]},
  { group:'About Us', size:'1600 × 1000, landscape', items:[ ['about-1','Family / team in the workshop','You and your father with the team'] ]}
];
const SLOT_INFO = Object.fromEntries(SLOTS.flatMap(g=>g.items.map(([id,label,hint])=>[id,{label,hint,size:g.size,group:g.group}])));
function applySlots(){
  const imgs=state.siteImages||{};
  $$('[data-slot]').forEach(el=>{
    const id=el.dataset.slot, url=imgs[id];
    let img=$(':scope > img.slot-img',el), tag=$(':scope > .slot-tag',el);
    if(url){
      if(!img){ img=document.createElement('img'); img.className='slot-img'; img.alt=(SLOT_INFO[id]||{}).label||''; img.decoding='async'; if(!id.startsWith('hero-1')) img.loading='lazy'; el.prepend(img); }
      if(img.getAttribute('src')!==url) img.src=url;
      el.classList.add('has-img'); tag&&tag.remove();
      if(id==='seg-lathe'&&lathe){ lathe.stop(); }
      if(id==='hero-3'&&hero){ hero.stop(); }
    } else {
      img&&img.remove(); el.classList.remove('has-img');
      if(preview() && SLOT_INFO[id] && !tag){ tag=document.createElement('span'); tag.className='slot-tag'; tag.innerHTML=`<b>Photo slot</b> · ${esc(SLOT_INFO[id].label)} · ${esc(SLOT_INFO[id].size.split(',')[0])}`; el.appendChild(tag); }
      if(!preview()&&tag) tag.remove();
    }
  });
}
/* hero slider */
function heroSlider(){
  const wrap=$('#heroSlides'); if(!wrap) return;
  const slides=$$('.hero-slide',wrap), dots=$$('.hero-dots [data-go]'); let i=0, timer=null;
  const go=n=>{ i=(n+slides.length)%slides.length; slides.forEach((s,k)=>s.classList.toggle('is-active',k===i)); dots.forEach((d,k)=>d.setAttribute('aria-selected',k===i));
    if(hero){ const lathSlide=slides[i].dataset.slot==='hero-3'&&!slides[i].classList.contains('has-img'); lathSlide?hero.start():hero.stop(); } };
  const play=()=>{ if(reduceMotion) return; clearInterval(timer); timer=setInterval(()=>go(i+1),6500); };
  dots.forEach(d=>d.addEventListener('click',()=>{ go(+d.dataset.go); play(); }));
  const sec=wrap.closest('.hero-photo'); sec.addEventListener('mouseenter',()=>clearInterval(timer)); sec.addEventListener('mouseleave',play);
  go(0); play();
}
/* =====================================================================
   BOOKING — call back / workshop visit (saved as leads, no online quotes)
   ===================================================================== */
const NEEDS = {
  wooden:['Sofa / diwan','Dining set','Bed','Mandir','Zula','Main door','Other'],
  modular:['Kitchen','Wardrobe','TV / living unit','Study','Full home','Office / commercial'],
  lathe:['Balusters / railing','Pillars','Balls / finials','Legs','Mandir parts','Thresholds'],
  any:['Wooden furniture','Modular kitchen / home interior','Lathe work','Not sure yet']
};
const WINDOWS = { morning:'Morning (10 AM – 1 PM)', afternoon:'Afternoon (1 – 4 PM)', evening:'Evening (4 – 7 PM)' };
const BOOK_TYPES = { callback:'Call back', visit:'Workshop visit' };
function bookingDays(n=14){
  const out=[], d=new Date(); d.setHours(0,0,0,0);
  for(let i=0; out.length<n && i<30; i++){
    const x=new Date(d); x.setDate(d.getDate()+i);
    if(CONFIG.closedDays.includes(x.getDay())) continue;
    const iso=x.getFullYear()+'-'+String(x.getMonth()+1).padStart(2,'0')+'-'+String(x.getDate()).padStart(2,'0');
    const label=(i===0?'Today, ':i===1?'Tomorrow, ':'')+x.toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'});
    out.push([iso,label]);
  }
  return out;
}
function bookingForm(seg, id, type='callback'){
  const head={ wooden:'Book a call about your furniture', modular:'Book a call about your kitchen or home', lathe:'Book a call about your turning work', any:'Book a call back or a workshop visit' }[seg];
  return `<form class="form enq" id="${id}" data-seg="${seg}" novalidate>
    <div class="enq-head"><h2>${head}</h2><p class="muted">Tell us a little about what you need. We'll call you to understand it properly, and plan a site visit if it's needed.</p></div>
    <div class="field"><span class="lbl" id="${id}-typelbl">How would you like to talk?</span><div class="pick pick-lg" role="radiogroup" aria-labelledby="${id}-typelbl">
      ${Object.entries(BOOK_TYPES).map(([k,l])=>`<label><input type="radio" name="btype" value="${k}" ${k===type?'checked':''}><span>${l}</span></label>`).join('')}</div></div>
    <div class="row2"><div class="field"><label for="${id}-name">Your name</label><input id="${id}-name" autocomplete="name" required></div>
      <div class="field"><label for="${id}-phone">Mobile number</label><input id="${id}-phone" type="tel" inputmode="tel" autocomplete="tel" placeholder="10-digit mobile" required></div></div>
    <div class="row2"><div class="field"><label for="${id}-date">Preferred day</label><select id="${id}-date">${bookingDays().map(([v,l])=>`<option value="${v}">${esc(l)}</option>`).join('')}</select></div>
      <div class="field"><label for="${id}-window">Preferred time</label><select id="${id}-window">${opt(WINDOWS,'morning')}</select></div></div>
    <div class="field"><span class="lbl" id="${id}-needlbl">What is it about?</span><div class="pick" role="group" aria-labelledby="${id}-needlbl">
      ${NEEDS[seg].map((n,i)=>`<label><input type="checkbox" name="need" value="${esc(n)}"><span>${esc(n)}</span></label>`).join('')}</div></div>
    ${seg==='lathe'
      ? `<div class="row2"><div class="field"><label for="${id}-qty">Quantity (optional)</label><input id="${id}-qty" placeholder="e.g. 40 pieces"></div><div class="field"><label for="${id}-size">Size (optional)</label><input id="${id}-size" placeholder="e.g. Ø 75 × L 900 mm"></div></div>`
      : `<div class="field"><label for="${id}-area">Area / locality</label><input id="${id}-area" placeholder="e.g. Gangapur Road"></div>`}
    <div class="field"><label for="${id}-msg">Anything we should know? (optional)</label><textarea id="${id}-msg" placeholder="New flat or renovation, timeline, your architect's name…"></textarea></div>
    <input type="text" name="company_site" tabindex="-1" autocomplete="off" class="hp" aria-hidden="true">
    <label class="toggle consent"><input type="checkbox" id="${id}-consent"> I agree to be contacted by Amar Furniture about this enquiry.</label>
    <p class="enq-err" role="alert" hidden></p>
    <button class="btn btn-brand" type="submit">Request booking</button>
    <p class="muted" style="font-size:13px">We're open <span data-days-text>${esc(CONFIG.days)}</span>, ${esc(CONFIG.hours)}. We confirm every booking by phone.</p>
  </form>`;
}
function renderEnquiries(){
  $$('[data-enquiry]').forEach(slot=>{ const seg=slot.dataset.enquiry; slot.innerHTML=bookingForm(seg,'enq-'+seg+(slot.dataset.suffix||'')); });
}
function openBooking(type='callback', seg='any'){
  const dlg=$('#bookDlg'), body=$('#bookDlgBody');
  body.innerHTML=bookingForm(seg,'dlg-'+seg,type);
  if(dlg.showModal){ dlg.showModal(); } else { dlg.setAttribute('open',''); }
  setTimeout(()=>$('#dlg-'+seg+'-name')?.focus(),50);
}
async function submitBooking(f){
  const id=f.id, seg=f.dataset.seg, v=s=>($('#'+id+'-'+s)?.value||'').trim(), err=$('.enq-err',f);
  const fail=(msg,el)=>{ err.hidden=false; err.textContent=msg; el&&el.focus(); };
  if($('.hp',f).value) return;                                   // bot
  const phone=v('phone').replace(/[^\d+]/g,''), digits=phone.replace(/\D/g,'').replace(/^91(?=\d{10}$)/,'');
  if(!v('name')) return fail('Please add your name.', $('#'+id+'-name'));
  if(!/^[6-9]\d{9}$/.test(digits)) return fail('Please enter a valid 10-digit mobile number.', $('#'+id+'-phone'));
  if(!$('#'+id+'-consent').checked) return fail('Please tick the box so we can call you.', $('#'+id+'-consent'));
  err.hidden=true;
  const type=$('input[name="btype"]:checked',f)?.value||'callback';
  const lead={ type, name:v('name').slice(0,80), phone:digits, segment:seg, needs:$$('input[name="need"]:checked',f).map(i=>i.value).slice(0,8),
    date:v('date'), window:v('window'), area:v('area').slice(0,80), qty:v('qty').slice(0,60), size:v('size').slice(0,60), message:v('msg').slice(0,1000),
    consent:true, status:'new', page:(MPA?location.pathname:(location.hash||'#home')).replace(/^[#/]+|\/$/g,'').slice(0,40)||'home' };
  const btn=$('button[type="submit"]',f); btn.disabled=true; btn.textContent='Sending…';
  try{
    if(fb){ await fb.db.collection(CONFIG.leadsCollection).add({...lead, createdAt:firebase.firestore.FieldValue.serverTimestamp()}); }
    else { state.admin.leads=state.admin.leads||[]; state.admin.leads.push({...lead,id:'L'+Date.now(),createdAt:{seconds:Date.now()/1000},_sample:true}); }
    const dayLabel=(bookingDays().find(d=>d[0]===lead.date)||[,''])[1];
    f.outerHTML=`<div class="form enq booked" role="status"><svg aria-hidden="true"><use href="#i-check"/></svg>
      <h2>Thank you, ${esc(lead.name.split(' ')[0])}.</h2>
      <p>We've received your request for a <b>${type==='visit'?'workshop visit':'call back'}</b> on <b>${esc(dayLabel)}</b>, ${esc(WINDOWS[lead.window].toLowerCase())}.</p>
      <p>Our team will call you on <b>${esc(digits.replace(/(\d{5})(\d{5})/,'$1 $2'))}</b> during working hours to confirm.${!fb?' <span class="badge sample">Preview: not saved</span>':''}</p></div>`;
  }catch(ex){ btn.disabled=false; btn.textContent='Request booking'; fail('Something went wrong. Please try again, or call us on '+CONFIG.phoneDisplay+'.'); }
}
document.addEventListener('submit',e=>{ const f=e.target.closest('form.enq'); if(!f) return; e.preventDefault(); submitBooking(f); });
document.addEventListener('click',e=>{
  const b=e.target.closest('[data-book]'); if(b){ e.preventDefault(); openBooking(b.dataset.book, b.dataset.seg||'any'); return; }
  if(e.target.closest('[data-close-dlg]') || e.target.id==='bookDlg'){ const d=$('#bookDlg'); d.close?d.close():d.removeAttribute('open'); }
});


/* =====================================================================
   ADMIN — Products and Projects tabs
   ===================================================================== */
const COL = { products: CONFIG.collection, projects: CONFIG.projectsCollection, reviews: CONFIG.reviewsCollection, leads: CONFIG.leadsCollection };
const blankProduct = () => ({ id:null, name:'', category:'furniture', kind:'sofa', wood:'teak', finish:'', dims:'', price:null, mrp:null, stock:'in', leadTime:'', description:'', images:[], featured:false, visible:true, sku:'', sort:null });
const blankProject = () => ({ id:null, title:'', segment:'wooden', kind:'other', material:'teak', location:'Nashik', year:new Date().getFullYear(), architect:'', summary:'', images:[], featured:false, visible:true });
const list = () => state.admin[state.tab];

async function renderAdmin(){
  const root=$('#adminRoot');
  if(!fb && !state.demo){
    root.innerHTML=`<div class="login-box">${LOGO.full}
      <h1 style="font-size:28px">Staff page</h1>
      <p class="muted">Firebase isn't connected yet, so this is running as a preview. Try the editor in demo mode; nothing you change here is saved.</p>
      <button class="btn btn-brand" type="button" id="demoBtn">Open demo editor</button>
      <p class="muted" style="font-size:13px">To go live: paste the Firebase web config into <span class="mono">CONFIG.firebase</span> at the top of the script.</p></div>`;
    $('#demoBtn').onclick=()=>{ state.demo=true; state.admin={ products:state.products.map(p=>({...p})), projects:state.projects.map(p=>({...p})), reviews:state.reviews.map(p=>({...p})), leads:(state.admin.leads&&state.admin.leads.length?state.admin.leads:SAMPLE_LEADS.map(p=>({...p}))) }; renderAdmin(); };
    return;
  }
  if(fb && !state.user){
    root.innerHTML=`<div class="login-box">${LOGO.full}<h1 style="font-size:28px">Staff login</h1><p class="muted">Sign in with an approved Google account to manage shop products and completed projects.</p>
      <button class="btn btn-line" type="button" id="gBtn"><svg><use href="#i-google"/></svg>Sign in with Google</button><p id="loginErr" style="color:var(--bad)" hidden></p></div>`;
    $('#gBtn').onclick=async()=>{ try{ await fb.auth.signInWithPopup(new firebase.auth.GoogleAuthProvider()); }catch(e){ const el=$('#loginErr'); el.hidden=false; el.textContent='Sign-in failed: '+(e.message||e.code); } };
    return;
  }
  if(fb && state.user && !CONFIG.adminEmails.includes(state.user.email)){
    root.innerHTML=`<div class="login-box"><h1 style="font-size:26px">Not authorised</h1><p class="muted">${esc(state.user.email)} isn't on the staff list. Ask Rahul to add it.</p><button class="btn btn-line" id="outBtn" type="button">Sign out</button></div>`;
    $('#outBtn').onclick=()=>fb.auth.signOut(); return;
  }
  if(fb && !state._adminLoaded){
    root.innerHTML='<div class="empty">Loading…</div>';
    try{
      const [a,b,c,d]=await Promise.all([fb.db.collection(COL.products).get(), fb.db.collection(COL.projects).get(), fb.db.collection(COL.reviews).get(), fb.db.collection(COL.leads).orderBy('createdAt','desc').limit(500).get()]);
      const m=q=>q.docs.map(d=>({id:d.id,...d.data()}));
      state.admin={ products:m(a), projects:m(b), reviews:m(c), leads:m(d) }; state._adminLoaded=true;
    }catch(e){ root.innerHTML=`<div class="empty">Couldn't load: ${esc(e.message)}. Check the Firestore rules for the <span class="mono">website_*</span> collections.</div>`; return; }
  }
  drawAdmin();
}


const LEAD_STATUS = { new:['New','warn'], called:['Called','ok'], visit:['Visit booked','ok'], quoted:['Quoted',''], won:['Won','ok'], lost:['Lost','bad'] };
const LEAD_STATUS_ORDER = { new:0, called:1, visit:2, quoted:3, won:4, lost:5 };
const leadBadge = s => { const x=LEAD_STATUS[s]||LEAD_STATUS.new; return `<span class="badge ${x[1]}">${x[0]}</span>`; };
const fmtTs = t => { const sec=t&&(t.seconds||(t.toDate&&t.toDate().getTime()/1000)); if(!sec) return '—'; const d=new Date(sec*1000); return d.toLocaleDateString('en-IN',{day:'numeric',month:'short'})+' '+d.toLocaleTimeString('en-IN',{hour:'numeric',minute:'2-digit'}); };
const fmtDay = iso => { if(!iso) return 'Any day'; const d=new Date(iso+'T00:00'); return isNaN(d)?iso:d.toLocaleDateString('en-IN',{weekday:'short',day:'numeric',month:'short'}); };
const STARS = n => '★★★★★'.slice(0,Math.max(0,Math.min(5,n||0)))+'☆☆☆☆☆'.slice(0,5-Math.max(0,Math.min(5,n||0)));
const REVIEW_SEG = { ...SEGMENTS, shop:'Shop product', any:'General' };
const TABS = {
  leads:{ label:'Leads', noun:'lead', key:'name', noToggles:true,
    blank:()=>({ id:null, type:'callback', name:'', phone:'', segment:'any', needs:[], date:'', window:'morning', area:'', message:'', status:'new', remarks:'', followUp:'', images:[] }),
    sort:l=>[...l].sort((a,b)=>(LEAD_STATUS_ORDER[a.status]??9)-(LEAD_STATUS_ORDER[b.status]??9)||(((b.createdAt||{}).seconds||0)-((a.createdAt||{}).seconds||0))),
    head:'<th>Received</th><th>Customer</th><th>Request</th><th>About</th><th>Status</th>',
    row:p=>`<td class="mono" style="white-space:nowrap">${esc(fmtTs(p.createdAt))}</td><td><b>${esc(p.name)}</b><br><a href="tel:+91${esc(p.phone)}" class="mono" onclick="event.stopPropagation()">${esc(p.phone)}</a>${p.area?`<br><span class="muted">${esc(p.area)}</span>`:''}</td>
      <td>${esc(BOOK_TYPES[p.type]||p.type)}<br><span class="muted">${esc(fmtDay(p.date))}${p.window?' · '+esc((WINDOWS[p.window]||'').split(' (')[0]):''}</span></td>
      <td>${esc(p.segment==='any'?'General':(SEGMENTS[p.segment]||''))}${(p.needs||[]).length?`<br><span class="muted">${esc(p.needs.join(', '))}</span>`:''}</td><td>${leadBadge(p.status)}</td>` },
  products:{ label:'Shop products', noun:'product', blank:blankProduct, key:'name',
    sort:l=>sortProducts(l,'featured'),
    head:'<th></th><th>Product</th><th>Category</th><th class="num">Price</th><th>Stock</th><th>On site</th>',
    row:p=>`<td><div class="thumb"><img src="${esc(imgFor(p))}" alt=""></div></td><td><b>${esc(p.name)}</b>${p.featured?' <span class="badge warn" style="height:20px;font-size:11px">Featured</span>':''}<br><span class="muted mono">${esc(p.sku||'')}</span></td>
      <td>${esc(CATS[p.category]||'')}</td><td class="num">${p.price!=null&&p.price!==''?inr(p.price):'<span class="muted">On request</span>'}</td><td>${stockBadge(p)}</td>` },
  projects:{ label:'Completed projects', noun:'project', blank:blankProject, key:'title',
    sort:l=>[...l].sort((a,b)=>(b.year||0)-(a.year||0)),
    head:'<th></th><th>Project</th><th>Department</th><th>Year</th><th>Photos</th><th>On site</th>',
    row:p=>`<td><div class="thumb"><img src="${esc(projImg(p))}" alt=""></div></td><td><b>${esc(p.title)}</b>${p.featured?' <span class="badge warn" style="height:20px;font-size:11px">Featured</span>':''}<br><span class="muted">${esc(p.location||'')}</span></td>
      <td>${esc(SEGMENTS[p.segment]||'')}</td><td>${esc(p.year||'')}</td><td class="num">${(p.images||[]).length}</td>` },
  reviews:{ label:'Customer reviews', noun:'review', blank:()=>({ id:null, name:'', area:'', segment:'any', rating:5, text:'', source:'Google', when:'', featured:true, visible:true, images:[] }), key:'name',
    sort:l=>[...l].sort((a,b)=>(!!b.featured-!!a.featured)||((b.rating||0)-(a.rating||0))),
    head:'<th>Customer</th><th>Review</th><th>Department</th><th>Rating</th><th>On site</th>',
    row:p=>`<td><b>${esc(p.name)}</b>${p.featured?' <span class="badge warn" style="height:20px;font-size:11px">Home page</span>':''}<br><span class="muted">${esc(p.area||'')}</span></td>
      <td style="max-width:280px"><span class="muted">${esc((p.text||'').slice(0,90))}${(p.text||'').length>90?'…':''}</span></td><td>${esc(REVIEW_SEG[p.segment]||'')}</td><td class="stars" aria-label="${p.rating} out of 5">${STARS(p.rating)}</td>` }
};
function drawAdmin(){
  if(state.tab==='images') return drawImagesTab();
  const root=$('#adminRoot'), T=TABS[state.tab];
  const rows=T.sort(list()), live=rows.filter(p=>p.visible!==false).length;
  root.innerHTML=`
    <div class="admin-top">
      <div style="display:grid;gap:6px"><span class="eyebrow">${state.demo?'Demo mode · changes are not saved':'Staff · '+esc(state.user.email)}</span><h1>Website content</h1>
        <div class="chips" role="tablist" aria-label="Content type">${Object.entries(TABS).map(([k,t])=>{ const n=k==='leads'?state.admin.leads.filter(l=>l.status==='new').length:0; return `<button class="chip" type="button" role="tab" data-tab="${k}" aria-pressed="${state.tab===k}">${t.label} (${state.admin[k].length})${n?` <span class="count-new">${n} new</span>`:''}</button>`; }).join('')}<button class="chip" type="button" role="tab" data-tab="images" aria-pressed="${state.tab==='images'}">Site photos (${Object.keys(state.siteImages||{}).length}/${Object.keys(SLOT_INFO).length})</button></div></div>
      <div style="display:flex;gap:8px;flex-wrap:wrap;align-items:center">${state.tab==='leads'?'':`<span class="muted" style="font-size:14px">${live} of ${rows.length} visible on the website</span>`}
        <button class="btn btn-brand" type="button" id="addBtn">+ Add ${T.noun}</button>${fb?'<button class="btn btn-line" type="button" id="outBtn">Sign out</button>':''}</div>
    </div>
    <div class="admin-layout">
      <div class="table-wrap"><table class="admin"><thead><tr>${T.head}</tr></thead>
        <tbody>${rows.map(p=>`<tr data-id="${esc(p.id)}" class="${state.editing&&state.editing.id===p.id?'sel':''}" tabindex="0" style="cursor:pointer">${T.row(p)}
          ${T.noToggles?'':`<td>${p.visible===false?'<span class="muted">Hidden</span>':'Visible'}</td>`}</tr>`).join('') || `<tr><td colspan="6" class="muted" style="padding:24px">Nothing yet. Click “Add ${T.noun}”.</td></tr>`}</tbody></table></div>
      <div class="editor" id="editor">${state.editing?'':`<div class="empty">Select a ${T.noun} to edit, or add a new one.</div>`}</div>
    </div>`;
  $$('[data-tab]',root).forEach(b=>b.onclick=()=>{ state.tab=b.dataset.tab; state.editing=null; drawAdmin(); });
  $('#addBtn').onclick=()=>{ state.editing=T.blank(); drawAdmin(); };
  if($('#outBtn')) $('#outBtn').onclick=()=>fb.auth.signOut();
  $$('tr[data-id]',root).forEach(tr=>{ const open=()=>{ const src=list().find(p=>p.id===tr.dataset.id); state.editing={...T.blank(),...src,images:[...(src.images||[])]}; drawAdmin(); };
    tr.onclick=open; tr.onkeydown=e=>{ if(e.key==='Enter') open(); }; });
  if(state.editing) drawEditor();
}

function drawImagesTab(){
  const root=$('#adminRoot'), imgs=state.siteImages||{}, filled=Object.keys(imgs).length, total=Object.keys(SLOT_INFO).length;
  root.innerHTML=`
    <div class="admin-top">
      <div style="display:grid;gap:6px"><span class="eyebrow">${state.demo?'Demo mode · changes are not saved':'Staff · '+esc(state.user.email)}</span><h1>Website content</h1>
        <div class="chips" role="tablist">${Object.entries(TABS).map(([k,t])=>`<button class="chip" type="button" data-tab="${k}" aria-pressed="false">${t.label} (${state.admin[k].length})</button>`).join('')}<button class="chip" type="button" data-tab="images" aria-pressed="true">Site photos (${filled}/${total})</button></div></div>
      <p class="muted" style="max-width:34em;font-size:14px">Upload a photo to any slot and it replaces the drawing on the website straight away. Use real photos of your own work. Photos are resized and compressed automatically.</p>
    </div>
    ${SLOTS.map(g=>`<section class="slot-group"><h2>${esc(g.group)} <span class="muted">· best size ${esc(g.size)}</span></h2><div class="slot-cards">
      ${g.items.map(([id,label,hint])=>`<div class="slot-card">
        <div class="slot-prev">${imgs[id]?`<img src="${esc(imgs[id])}" alt="">`:'<span>No photo yet</span>'}</div>
        <div class="slot-meta"><b>${esc(label)}</b>${hint?`<span class="muted">${esc(hint)}</span>`:''}
          <div class="slot-btns"><label class="btn btn-line btn-sm" for="sf-${id}">${imgs[id]?'Replace':'Upload'}</label><input type="file" id="sf-${id}" accept="image/*" hidden data-slotfile="${id}">
          ${imgs[id]?`<button class="btn btn-ghost btn-sm" type="button" data-slotrm="${id}">Remove</button>`:''}</div></div></div>`).join('')}
    </div></section>`).join('')}`;
  $$('[data-tab]',root).forEach(b=>b.onclick=()=>{ state.tab=b.dataset.tab; state.editing=null; drawAdmin(); });
  $$('[data-slotfile]',root).forEach(inp=>inp.onchange=()=>inp.files[0]&&uploadSlot(inp.dataset.slotfile,inp.files[0]));
  $$('[data-slotrm]',root).forEach(b=>b.onclick=()=>removeSlot(b.dataset.slotrm));
}
async function uploadSlot(id,file){
  toast('Uploading photo…');
  try{
    const blob=await compress(file, id.startsWith('hero')?2200:1600);
    let url;
    if(state.demo||!fb){ url=await new Promise(r=>{ const fr=new FileReader(); fr.onload=()=>r(fr.result); fr.readAsDataURL(blob); }); }
    else { const ref=fb.storage.ref(`website/site/${id}-${Date.now()}.webp`); await ref.put(blob,{contentType:'image/webp',cacheControl:'public,max-age=31536000'}); url=await ref.getDownloadURL();
      await fb.db.collection(CONFIG.settingsCollection).doc('images').set({[id]:url},{merge:true}); }
    state.siteImages={...state.siteImages,[id]:url}; if(!state.demo) store.set('af-site-images',JSON.stringify(state.siteImages)); applySlots(); drawImagesTab(); toast(state.demo?'Photo placed (demo, not saved)':'Photo is live on the website');
  }catch(e){ toast('Upload failed: '+(e.code||e.message)); }
}
async function removeSlot(id){
  try{
    if(!state.demo&&fb) await fb.db.collection(CONFIG.settingsCollection).doc('images').update({[id]:firebase.firestore.FieldValue.delete()});
    const n={...state.siteImages}; delete n[id]; state.siteImages=n; if(!state.demo) store.set('af-site-images',JSON.stringify(n)); applySlots(); drawImagesTab(); toast('Photo removed');
  }catch(e){ toast('Couldn’t remove: '+(e.code||e.message)); }
}
function opt(obj,sel,keys){ return (keys||Object.keys(obj)).map(k=>`<option value="${k}"${String(k)===String(sel)?' selected':''}>${esc(obj[k])}</option>`).join(''); }
const numOrNull=v=>{ v=String(v??'').replace(/[^\d.]/g,''); return v===''?null:Number(v); };
function field(id,label,val,extra=''){ return `<div class="field"><label for="f-${id}">${label}</label><input id="f-${id}" value="${esc(val??'')}" ${extra}></div>`; }
function drawEditor(){
  const e=state.editing, box=$('#editor'), tab=state.tab, T=TABS[tab];
  const photos=`<div class="field"><span class="lbl">Photos</span><span class="hint">First photo is the cover. Click a photo to make it the cover. Photos are resized to 1600 px before upload.</span>
      <div class="img-list">${e.images.map((u,i)=>`<div class="img-item"><img src="${esc(u)}" alt="" data-cover="${i}" style="cursor:pointer">${i===0?'<span class="first">Cover</span>':''}<button type="button" data-rm="${i}" aria-label="Remove photo">×</button></div>`).join('')}</div>
      <label class="drop" id="drop" for="f-files">Drop photos here or click to choose</label><input id="f-files" type="file" accept="image/*" multiple hidden></div>`;
  const body = tab==='products' ? `
    ${field('name','Product name',e.name,'placeholder="e.g. Teak Wooden Sofa, 3-seater"')}
    <div class="row2"><div class="field"><label for="f-category">Category</label><select id="f-category">${opt(CATS,e.category)}</select></div>
      <div class="field"><label for="f-kind">Type</label><select id="f-kind">${opt(KINDS,e.kind,PRODUCT_KINDS)}</select></div></div>
    <div class="row2"><div class="field"><label for="f-wood">Wood</label><select id="f-wood">${opt(WOODS,e.wood)}</select></div>${field('finish','Finish',e.finish,'placeholder="PU matt, natural oil…"')}</div>
    <div class="field"><label for="f-dims">Size in mm</label><input id="f-dims" value="${esc(e.dims)}" placeholder="L × W × H, or Ø 75 × L 900"><span class="hint">Shown as “Size (mm)” on the product page.</span></div>
    <div class="row2">${field('price','Price (₹)',e.price,'inputmode="numeric" placeholder="Empty = “on request”"')}${field('mrp','MRP (₹, optional)',e.mrp,'inputmode="numeric" placeholder="Shown struck-through"')}</div>
    <div class="row2"><div class="field"><label for="f-stock">Availability</label><select id="f-stock">${opt(Object.fromEntries(Object.entries(STOCK).map(([k,v])=>[k,v[0]])),e.stock)}</select></div>${field('lead','Lead time',e.leadTime,'placeholder="e.g. 3 weeks"')}</div>
    <div class="field"><label for="f-desc">Description</label><textarea id="f-desc" placeholder="What it is, joinery, care, what's included…">${esc(e.description)}</textarea></div>
    ${photos}
    <div class="row2">${field('sku','Product code',e.sku,'placeholder="Auto if empty"')}${field('sort','Sort order',e.sort,'inputmode="numeric" placeholder="1 = first"')}</div>`
  : tab==='projects' ? `
    ${field('title','Project name',e.title,'placeholder="e.g. L-shaped kitchen, 3BHK at Gangapur Road"')}
    <div class="row2"><div class="field"><label for="f-segment">Department</label><select id="f-segment">${opt(SEGMENTS,e.segment)}</select></div>
      <div class="field"><label for="f-kind">Main item</label><select id="f-kind">${opt(KINDS,e.kind,PROJECT_KINDS)}</select></div></div>
    <div class="row3">${field('location','Location',e.location)}${field('year','Year',e.year,'inputmode="numeric"')}<div class="field"><label for="f-material">Material</label><select id="f-material">${opt(MATERIALS,e.material)}</select></div></div>
    ${field('architect','Architect / designer (optional)',e.architect,'placeholder="Credit them; they share it"')}
    <div class="field"><label for="f-summary">What we did</label><textarea id="f-summary" placeholder="Scope, materials, finish, anything special about the site…">${esc(e.summary)}</textarea></div>
    ${photos}`
  : tab==='leads' ? `
    ${e._sample?'<div class="notice"><span><b>Sample lead</b> to show how bookings appear.</span></div>':''}
    <div class="row2">${field('name','Customer name',e.name)}<div class="field"><label for="f-phone">Mobile</label><input id="f-phone" value="${esc(e.phone)}" inputmode="tel">${e.phone?`<a class="btn btn-line btn-sm" style="margin-top:6px;justify-self:start" href="tel:+91${esc(e.phone)}">Call ${esc(e.phone)}</a>`:''}</div></div>
    <div class="row3"><div class="field"><label for="f-type">Request</label><select id="f-type">${opt(BOOK_TYPES,e.type)}</select></div>
      <div class="field"><label for="f-segment">About</label><select id="f-segment">${opt({...SEGMENTS,any:'General'},e.segment)}</select></div>
      <div class="field"><label for="f-status">Status</label><select id="f-status">${opt(Object.fromEntries(Object.entries(LEAD_STATUS).map(([k,v])=>[k,v[0]])),e.status)}</select></div></div>
    <div class="row2">${field('date','Preferred day',e.date,'type="date"')}<div class="field"><label for="f-window">Preferred time</label><select id="f-window">${opt(WINDOWS,e.window)}</select></div></div>
    ${field('area','Area',e.area)}
    ${field('needs','Interested in',(e.needs||[]).join(', '))}
    ${(e.qty||e.size)?`<p class="muted" style="font-size:14px">Quantity: ${esc(e.qty||'—')} · Size: ${esc(e.size||'—')}</p>`:''}
    <div class="field"><label for="f-message">Customer's message</label><textarea id="f-message">${esc(e.message)}</textarea></div>
    <div class="field"><label for="f-remarks">Our remarks (staff only)</label><textarea id="f-remarks" placeholder="What was discussed on the call, site visit plan, next step…">${esc(e.remarks)}</textarea></div>
    ${field('followUp','Next follow-up',e.followUp,'type="date"')}
    <p class="muted" style="font-size:13px">Received ${esc(fmtTs(e.createdAt))}${e.page?` from the ${esc(e.page)} page`:''}.</p>`
  : `
    <div class="row2">${field('name','Customer name',e.name,'placeholder="As shown on Google, e.g. Sameer P."')}${field('area','Area / role',e.area,'placeholder="e.g. College Road, or Architect"')}</div>
    <div class="row3"><div class="field"><label for="f-segment">About</label><select id="f-segment">${opt(REVIEW_SEG,e.segment)}</select></div>
      <div class="field"><label for="f-rating">Rating</label><select id="f-rating">${opt({5:'★★★★★ 5',4:'★★★★ 4',3:'★★★ 3'},e.rating)}</select></div>
      <div class="field"><label for="f-source">Source</label><select id="f-source">${opt({Google:'Google',WhatsApp:'WhatsApp',JustDial:'JustDial','In person':'In person'},e.source)}</select></div></div>
    <div class="field"><label for="f-text">Review text</label><textarea id="f-text" placeholder="Paste the customer's words exactly. Don't edit the meaning.">${esc(e.text)}</textarea><span class="hint">Only publish real reviews, with the customer's permission.</span></div>
    ${field('when','When (optional)',e.when,'placeholder="e.g. Aug 2026"')}`;
  box.innerHTML=`<form class="form" id="pForm" novalidate>
    <div style="display:flex;justify-content:space-between;align-items:center;gap:12px"><h2 style="font-size:22px">${e.id?'Edit':'New'} ${T.noun}</h2><button class="btn btn-ghost btn-sm" type="button" id="closeEd">Close</button></div>
    ${body}
    ${T.noToggles?'':`<label class="toggle"><input type="checkbox" id="f-visible" ${e.visible!==false?'checked':''}> Show on website</label>
    <label class="toggle"><input type="checkbox" id="f-featured" ${e.featured?'checked':''}> Feature on home page</label>`}
    <p id="edErr" role="alert" style="color:var(--bad);font-size:14px" hidden></p>
    <div style="display:flex;gap:8px;flex-wrap:wrap"><button class="btn btn-brand" type="submit" id="saveBtn">${e.id?'Save changes':'Add '+T.noun}</button>
      ${e.id?'<button class="btn btn-ghost" type="button" id="delBtn">Delete</button>':''}</div>
    <div id="delConfirm" hidden></div>
  </form>`;
  const f=$('#pForm'), val=id=>($('#f-'+id)?.value??'').trim();
  const sync=()=>{
    if(tab==='products') Object.assign(e,{ name:val('name'), category:val('category'), kind:val('kind'), wood:val('wood'), finish:val('finish'), dims:val('dims'), price:numOrNull(val('price')), mrp:numOrNull(val('mrp')), stock:val('stock'), leadTime:val('lead'), description:val('desc'), sku:val('sku'), sort:numOrNull(val('sort')) });
    else if(tab==='projects') Object.assign(e,{ title:val('title'), segment:val('segment'), kind:val('kind'), location:val('location'), year:numOrNull(val('year')), material:val('material'), architect:val('architect'), summary:val('summary') });
    else if(tab==='leads') Object.assign(e,{ name:val('name'), phone:val('phone').replace(/\D/g,'').slice(-10), type:val('type'), segment:val('segment'), status:val('status'), date:val('date'), window:val('window'), area:val('area'), needs:val('needs').split(',').map(x=>x.trim()).filter(Boolean), message:val('message'), remarks:val('remarks'), followUp:val('followUp') });
    else Object.assign(e,{ name:val('name'), area:val('area'), segment:val('segment'), rating:Number(val('rating')), source:val('source'), text:val('text'), when:val('when') });
    if(!T.noToggles){ e.visible=$('#f-visible').checked; e.featured=$('#f-featured').checked; } };
  $('#closeEd').onclick=()=>{ state.editing=null; drawAdmin(); };
  $$('[data-rm]',f).forEach(b=>b.onclick=()=>{ sync(); e.images.splice(+b.dataset.rm,1); drawEditor(); });
  $$('[data-cover]',f).forEach(im=>im.onclick=()=>{ sync(); const i=+im.dataset.cover; e.images.unshift(...e.images.splice(i,1)); drawEditor(); });
  const drop=$('#drop'), files=$('#f-files');
  if(drop){
    files.onchange=()=>{ sync(); addPhotos([...files.files]); };
    ['dragenter','dragover'].forEach(ev=>drop.addEventListener(ev,x=>{x.preventDefault(); drop.classList.add('over');}));
    ['dragleave','drop'].forEach(ev=>drop.addEventListener(ev,x=>{x.preventDefault(); drop.classList.remove('over');}));
    drop.addEventListener('drop',x=>{ sync(); addPhotos([...x.dataTransfer.files].filter(f=>f.type.startsWith('image/'))); });
  }
  f.onsubmit=async ev=>{ ev.preventDefault(); sync(); await saveItem(); };
  if($('#delBtn')) $('#delBtn').onclick=()=>{ const c=$('#delConfirm'); c.hidden=false; c.innerHTML=`<div class="confirm-row">Delete “${esc(e[T.key])}” permanently? <button class="btn btn-danger btn-sm" type="button" id="delYes">Delete</button><button class="btn btn-line btn-sm" type="button" id="delNo">Keep it</button></div>`;
    $('#delNo').onclick=()=>{ c.hidden=true; }; $('#delYes').onclick=deleteItem; };
}
async function compress(file, max=1600){
  const bmp = await createImageBitmap(file).catch(()=>null);
  if(!bmp) return file;
  const s=Math.min(1, max/Math.max(bmp.width,bmp.height)), c=document.createElement('canvas');
  c.width=Math.round(bmp.width*s); c.height=Math.round(bmp.height*s); c.getContext('2d').drawImage(bmp,0,0,c.width,c.height);
  return await new Promise(r=>c.toBlob(b=>r(b||file),'image/webp',.82));
}
async function addPhotos(files){
  if(!files.length) return; const e=state.editing, drop=$('#drop'), folder=state.tab==='products'?'products':'projects';
  for(const [i,file] of files.entries()){
    drop.textContent=`Processing photo ${i+1} of ${files.length}…`;
    const blob=await compress(file);
    if(state.demo){ e.images.push(await new Promise(r=>{ const fr=new FileReader(); fr.onload=()=>r(fr.result); fr.readAsDataURL(blob); })); continue; }
    try{
      const id = e.id || (e._tmpId ||= fb.db.collection(COL[state.tab]).doc().id);
      const ref = fb.storage.ref(`website/${folder}/${id}/${Date.now()}-${i}.webp`);
      await ref.put(blob,{contentType:'image/webp',cacheControl:'public,max-age=31536000'});
      e.images.push(await ref.getDownloadURL());
    }catch(err){ toast('Upload failed: '+(err.code||err.message)); }
  }
  drawEditor(); toast(files.length>1?`${files.length} photos added`:'Photo added');
}

async function saveItem(){
  const e=state.editing, err=$('#edErr'), tab=state.tab, T=TABS[tab];
  if(!e[T.key] || (tab==='reviews' && !e.text) || (tab==='leads' && !/^\d{10}$/.test(e.phone||''))){ err.hidden=false; err.textContent= tab==='leads' ? 'Add the customer name and a 10-digit mobile number.' : tab==='reviews' ? 'Add the customer name and the review text before saving.' : `Add a ${T.noun} name before saving.`; $('#f-'+(e[T.key]?(tab==='leads'?'phone':'text'):T.key)).focus(); return; }
  let data;
  if(tab==='products'){ if(!e.sku) e.sku={furniture:'AF-F',mandir:'AF-M',lathe:'AF-L'}[e.category]+String(Math.floor(100+Math.random()*900));
    data={ name:e.name, category:e.category, kind:e.kind, wood:e.wood, finish:e.finish, dims:e.dims, price:e.price, mrp:e.mrp, stock:e.stock, leadTime:e.leadTime, description:e.description, images:e.images, featured:e.featured, visible:e.visible, sku:e.sku, sort:e.sort }; }
  else if(tab==='projects') data={ title:e.title, segment:e.segment, kind:e.kind, material:e.material, location:e.location, year:e.year, architect:e.architect, summary:e.summary, images:e.images, featured:e.featured, visible:e.visible };
  else if(tab==='leads') data={ name:e.name, phone:e.phone, type:e.type, segment:e.segment, status:e.status, date:e.date, window:e.window, area:e.area, needs:e.needs, message:e.message, remarks:e.remarks||'', followUp:e.followUp||'', consent:e.consent!==false };
  else data={ name:e.name, area:e.area, segment:e.segment, rating:e.rating, source:e.source, text:e.text, when:e.when, featured:e.featured, visible:e.visible };
  const btn=$('#saveBtn'); btn.disabled=true; btn.textContent='Saving…';
  try{
    if(state.demo){
      if(!e.id){ e.id='d'+Date.now(); list().push({...data,id:e.id,createdAt:{seconds:Date.now()/1000}}); }
      else Object.assign(list().find(p=>p.id===e.id),data);
    } else {
      const col=fb.db.collection(COL[tab]), ts=firebase.firestore.FieldValue.serverTimestamp();
      if(!e.id){ const id=e._tmpId||col.doc().id; await col.doc(id).set({...data,createdAt:ts,updatedAt:ts}); e.id=id; list().push({...data,id}); }
      else { await col.doc(e.id).update({...data,updatedAt:ts}); Object.assign(list().find(p=>p.id===e.id),data); }
    }
    syncPublic(); toast(state.demo?'Saved in demo (not stored)':(state.tab==='leads'?'Lead updated':'Saved. It’s live on the website.')); drawAdmin();
  }catch(ex){ btn.disabled=false; btn.textContent='Save changes'; err.hidden=false; err.textContent='Couldn’t save: '+(ex.code||ex.message)+'. Check you are signed in as staff.'; }
}
async function deleteItem(){
  const e=state.editing;
  try{
    if(!state.demo) await fb.db.collection(COL[state.tab]).doc(e.id).delete();
    state.admin[state.tab]=list().filter(p=>p.id!==e.id); state.editing=null; syncPublic(); toast('Deleted'); drawAdmin();
  }catch(ex){ toast('Couldn’t delete: '+(ex.code||ex.message)); }
}
function syncPublic(){ ['products','projects','reviews'].forEach(k=>state[k]=state.admin[k].filter(p=>p.visible!==false)); renderFeatured(); renderProjects(); renderReviews(); }


