let hero=null, lathe=null;
const TITLES={ home:'Amar Furniture, Nashik · Wooden Furniture, Modular Kitchens & Lathe Works', wooden:'Wooden Furniture · Amar Furniture, Nashik', modular:'Modular Kitchen & Home Interior · Amar Furniture, Nashik',
  lathe:'Lathe Works · Amar Furniture, Nashik', shop:'Shop · Amar Furniture, Nashik', projects:'Completed Projects · Amar Furniture, Nashik', about:'About Us · Amar Furniture, Nashik', contact:'Contact Us · Amar Furniture, Nashik', admin:'Staff · Amar Furniture' };
let firstRoute=true;
function currentRoute(){
  if(MPA){
    const q=new URLSearchParams(location.search), page=document.body.dataset.page;
    if(page==='shop' && q.get('p')) return { view:'product', id:q.get('p') };
    if(page==='projects' && q.get('id')) return { view:'project', id:q.get('id') };
    if(page==='shop' && q.get('cat') && firstRoute && CATS[q.get('cat')]) state.cat=q.get('cat');
    return { view:page, id:null, anchor: location.hash ? document.getElementById(location.hash.slice(1)) : null };
  }
  const h=(location.hash||'#home').slice(1)||'home';
  if(h.startsWith('p-')) return { view:'product', id:h.slice(2) };
  if(h.startsWith('pr-')) return { view:'project', id:h.slice(3) };
  if($(`[data-view="${h}"]`)) return { view:h };
  const anchor=document.getElementById(h);
  return { view: anchor&&anchor.closest('[data-view]') ? anchor.closest('[data-view]').dataset.view : 'home', anchor };
}
function setMeta(title, desc, url, jsonld){
  document.title=title;
  if(!MPA) return;
  const m=(sel,attr,val)=>{ let el=$(sel); if(!el){ el=document.createElement(sel.startsWith('link')?'link':'meta'); const [,k,v]=sel.match(/\[(\w+)="([^"]+)"\]/); el.setAttribute(k,v); document.head.appendChild(el);} el.setAttribute(attr,val); };
  if(desc){ m('meta[name="description"]','content',desc); m('meta[property="og:description"]','content',desc); }
  m('meta[property="og:title"]','content',title); m('link[rel="canonical"]','href',url); m('meta[property="og:url"]','content',url);
  let ld=$('#ld-dynamic'); if(!ld){ ld=document.createElement('script'); ld.type='application/ld+json'; ld.id='ld-dynamic'; document.head.appendChild(ld); }
  ld.textContent=jsonld?JSON.stringify(jsonld):'';
}
function route(ev){
  const r=currentRoute(), view=r.view, id=r.id, anchor=r.anchor;
  $$('[data-view]').forEach(v=>v.hidden = v.dataset.view!==view);
  const navFor = view==='product' ? 'shop' : view==='project' ? (state.projects.find(j=>j.id===id)||{}).segment : view;
  $$('[data-nav]').forEach(a=>{ if(a.dataset.nav===navFor) a.setAttribute('aria-current','page'); else a.removeAttribute('aria-current'); });
  $('#nav').classList.remove('open'); $('#menuBtn').setAttribute('aria-expanded','false');
  if(!MPA) document.title=TITLES[view]||TITLES.home;
  if(view==='shop') renderShop();
  if(view==='product') renderProduct(id);
  if(view==='project') renderProjectDetail(id);
  if(view==='admin') renderAdmin();
  if(view!=='home') hero&&hero.stop();
  if(view==='lathe' && $('#latheCanvas') && !(state.siteImages||{})['seg-lathe']){ if(!lathe) lathe=latheScene($('#latheCanvas'),{style:'pillar',species:'teak'}); requestAnimationFrame(()=>lathe.start()); } else lathe&&lathe.stop();
  requestAnimationFrame(paintStatic);
  if(anchor) requestAnimationFrame(()=>anchor.scrollIntoView({behavior:reduceMotion?'auto':'smooth'}));
  else if(ev) window.scrollTo({top:0,behavior:'instant'});
  firstRoute=false;
}
function paintStatic(){
  $$('canvas[data-art]').forEach(c=>{ if(!c._done && c.getBoundingClientRect().width){ paintArtCanvas(c); c._done=true; } });
  $$('canvas[data-grain]').forEach(c=>{ if(!c._done && c.getBoundingClientRect().width){ paintGrainPanel(c,c.dataset.grain); c._done=true; } });
}
function applyTheme(t){ const root=document.documentElement; if(t) root.setAttribute('data-theme',t); const dark = t ? t==='dark' : matchMedia('(prefers-color-scheme: dark)').matches; $('#themeBtn use').setAttribute('href', dark?'#i-sun':'#i-moon'); }
function fillStatic(){
  $$('[data-wa]').forEach(a=>a.href=wa(a.dataset.wa));
  $$('[data-phone-text]').forEach(el=>el.textContent=CONFIG.phoneDisplay);
  $$('[data-address]').forEach(el=>el.textContent=CONFIG.address);
  $$('[data-hours]').forEach(el=>el.textContent=CONFIG.hours+', '+CONFIG.days);
  $$('[data-days-text]').forEach(el=>el.textContent=CONFIG.days);
  $$('[data-maps]').forEach(a=>a.href=CONFIG.mapsUrl);
  $$('[data-year]').forEach(el=>el.textContent=new Date().getFullYear());
  $$('[data-years]').forEach(el=>el.textContent=new Date().getFullYear()-1991);
  $$('[data-social]').forEach(a=>{ const u=CONFIG[a.dataset.social]; if(u) a.href=u; else a.closest('li').hidden=true; });
}
document.addEventListener('click',ev=>{
  const c=ev.target.closest('[data-cat]'); if(c){ state.cat=c.dataset.cat; renderShop(); return; }
  const ps=ev.target.closest('[data-projseg]'); if(ps){ state.projSeg=ps.dataset.projseg; renderProjects(); return; }
  const g=ev.target.closest('[data-go-cat]'); if(g){ state.cat=g.dataset.goCat; }
  const th=ev.target.closest('.thumbs button'); if(th){ $('#pdMain').src=th.dataset.src; $$('.thumbs button').forEach(b=>b.setAttribute('aria-current', b===th)); }
  const cp=ev.target.closest('[data-copy="phone"]'); if(cp){ navigator.clipboard?.writeText(CONFIG.phoneDisplay).then(()=>toast('Number copied'),()=>toast(CONFIG.phoneDisplay)); }
});
$('#q')?.addEventListener('input',e=>{ state.q=e.target.value; renderShop(); });
$('#sort')?.addEventListener('change',e=>{ state.sort=e.target.value; renderShop(); });
$('#menuBtn').addEventListener('click',()=>{ const n=$('#nav'), open=!n.classList.contains('open'); n.classList.toggle('open',open); $('#menuBtn').setAttribute('aria-expanded',open); });
$('#themeBtn').addEventListener('click',()=>{ const cur=document.documentElement.getAttribute('data-theme') || (matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light'); const next=cur==='dark'?'light':'dark'; store.set('af-theme',next); applyTheme(next); });
if(!MPA) window.addEventListener('hashchange',route); else window.addEventListener('hashchange',()=>{ const a=location.hash&&document.getElementById(location.hash.slice(1)); a&&a.scrollIntoView({behavior:reduceMotion?'auto':'smooth'}); });
let rT; window.addEventListener('resize',()=>{ clearTimeout(rT); rT=setTimeout(()=>{ hero&&hero.resize(); lathe&&lathe.resize(); },150); });

/* boot */
(async function(){
  applyTheme(store.get('af-theme'));
  fillStatic(); renderEnquiries(); renderTrust();
  if(CONFIG.firebase.apiKey){ try{ const c=JSON.parse(store.get('af-site-images')||'null'); if(c) state.siteImages=c; }catch(e){} }
  hero=$('#heroCanvas') ? latheScene($('#heroCanvas'),{style:'baluster',species:'teak',shavings:false}) : null;
  route(); renderFeatured(); renderProjects(); applySlots(); heroSlider();
  await loadData();
  renderFeatured(); renderProjects(); renderReviews(); route(); applySlots();
  if(fb) fb.auth.onAuthStateChanged(u=>{ state.user=u; state._adminLoaded=false; if(!$('[data-view="admin"]').hidden) renderAdmin(); });
})();
